from .errors import WFormatError

__all__ = ["encode_uvarint", "decode_uvarint", "MAX_SHIFT"]

MAX_SHIFT = 63


def encode_uvarint(value):
    """把非负整数编码为 LEB128 字节串。"""
    if not isinstance(value, int) or value < 0:
        raise ValueError("uvarint 只能编码非负整数")
    out = bytearray()
    while True:
        group = value & 0x7F
        value >>= 7
        if value:
            out.append(group | 0x80)
        else:
            out.append(group)
            return bytes(out)


def decode_uvarint(buf, pos=0):
    """从 ``buf[pos:]`` 解出一个 uvarint，返回 ``(value, next_pos)``。"""
    if pos >= len(buf):
        raise WFormatError("truncated", "uvarint 数据不足")

    result = 0
    shift = 0

    while pos < len(buf):
        byte = buf[pos]
        pos += 1

        result |= (byte & 0x7F) << shift

        if not (byte & 0x80):
            # 没有继续位，完成
            return result, pos

        shift += 7
        if shift > MAX_SHIFT:
            raise WFormatError("varint", "变长整数过长")

    # 循环结束但没有遇到终止字节
    raise WFormatError("truncated", "变长整数不完整")

